package main

import (
	"bufio"
	"fmt"
	"os"
)

type Node struct {
	char     byte
	index    int
	nextArr  [26]*Node
	hasCul   bool
	isSame   bool
	nextList []*Node
	countArr []int64
}

func NewNode(c byte, idx, n int) *Node {
	return &Node{
		char:     c,
		index:    idx,
		countArr: make([]int64, n),
	}
}

func (n *Node) addNext(index int, node *Node) {
	if n.nextArr[index] == nil {
		n.nextArr[index] = node
		n.nextList = append(n.nextList, node)
	}
}

func find(node *Node, n int) {
	if node.hasCul {
		return
	}
	node.countArr[0]++
	for _, next := range node.nextList {
		find(next, n)
		for i := 0; i < n; i++ {
			if next.countArr[i] > 0 {
				if i+1 < n {
					node.countArr[i+1] += next.countArr[i]
				}
			}
		}
	}
	node.hasCul = true
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	n := 0
	fmt.Sscanf(scanner.Text(), "%d", &n)

	scanner.Scan()
	var k int64
	fmt.Sscanf(scanner.Text(), "%d", &k)

	scanner.Scan()
	str := scanner.Text()

	letters := [26]bool{}
	nodes := make([]*Node, 0, n)

	for i := 0; i < len(str); i++ {
		c := str[i]
		node := NewNode(c, i, n)
		if letters[c-'a'] {
			node.isSame = true
		} else {
			letters[c-'a'] = true
		}
		nodes = append(nodes, node)
	}

	for i := 0; i < len(nodes); i++ {
		ai := nodes[i]
		for j := i + 1; j < len(nodes); j++ {
			aj := nodes[j]
			ai.addNext(int(aj.char-'a'), aj)
		}
	}

	for _, node := range nodes {
		find(node, n)
	}

	totalCountArray := make([]int64, n)
	for i := 0; i < n; i++ {
		for _, node := range nodes {
			if !node.isSame {
				totalCountArray[i] += node.countArr[i]
			}
		}
	}

	var totalCost int64
	var selectCount int64
	for i := n - 1; i >= 0; i-- {
		if selectCount+totalCountArray[i] < k {
			totalCost += int64(n-1-i) * totalCountArray[i]
			selectCount += totalCountArray[i]
		} else {
			over := (selectCount + totalCountArray[i]) - k
			totalCost += int64(n-1-i) * (totalCountArray[i] - over)
			selectCount += (totalCountArray[i] - over)
			break
		}
	}

	if selectCount < k {
		if selectCount == k-1 {
			fmt.Println(totalCost + int64(n))
		} else {
			fmt.Println(-1)
		}
	} else {
		fmt.Println(totalCost)
	}
}

